CREATE DATABASE IF NOT EXISTS `base_qualite` DEFAULT CHARACTER SET latin1 COLLATE latin1_swedish_ci;
USE `base_qualite`;

DELIMITER $$
--
-- Procédures
--
DROP PROCEDURE IF EXISTS `sp_mettre_a_jour_validation_bv`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_mettre_a_jour_validation_bv` (IN `p_id_validation_bv` INT, IN `p_champs` TEXT, IN `p_valeurs` TEXT)   BEGIN
  SET @sql = CONCAT('UPDATE validation_bv SET ', 
                   REPLACE(p_champs, ',', ' = ?, '), 
                   ' = ? WHERE ID_VALIDATION_BV = ?');
  
  PREPARE stmt FROM @sql;
  
  -- Exécution dynamique selon le nombre de paramètres
  SET @params = CONCAT(p_valeurs, ',', p_id_validation_bv);
  EXECUTE stmt USING @params;
  
  DEALLOCATE PREPARE stmt;
END$$

DROP PROCEDURE IF EXISTS `sp_valider_analyse_bv`$$
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_valider_analyse_bv` (IN `p_id_analyse_kko` INT, IN `p_validateur_id` INT, IN `p_statut` VARCHAR(20))   BEGIN
  DECLARE v_exists INT;
  
  -- Vérifier si l'analyse existe déjà dans validation_bv
  SELECT COUNT(*) INTO v_exists 
  FROM validation_bv 
  WHERE ID_ANALYSE_KKO = p_id_analyse_kko;
  
  IF v_exists = 0 THEN
    -- Insérer l'analyse dans validation_bv
    INSERT INTO validation_bv (
      ID_ANALYSE_KKO, VALIDATEUR_ID, STATUT_VALIDATION,
      CODE_SECRET_CODIFICATION, REF_DEMANDE, AUT_DEMANDE,
      RAISONSOCIALE_EXPORTATEUR, NUM_LOTS, NOM_ANALYSEUR,
      CAMP_DEMANDE, VILLE_DEMANDE, DATE_ANALYSE_KKO,
      POIDS_BRISURES, POIDS_DECHET, POIDS_CRABOT, POIDS_ETRANGERES,
      GRAINAGE, TAUXHUMIDITE, MOISIE_CALCULE, MITEE_CALCULE,
      ARDOISEE_CALCULE, PLATE_CALCULE, GERMEE_CALCULE, VIOLETTE_CALCULE,
      NORME_IVOIRIENNE, NORME_INTERNATIONALE, CONFORME, REMARQUE,
      POIDS_DECLARATION, POIDS_ECHAN_ANALYSE_KKO, POIDS_TOTAL_ECHANTILLON,
      MOISIE_TOTAL, MITEE_TOTAL, ARDOISEE_TOTAL, PLATE_TOTAL, GERMEE_TOTAL, VIOLETTE_TOTAL,
      TAUXBRISURE, TAUXDECHETS, TAUXCRABOT, TAUXMATIERE, TOTAL_DEFECTUEUSES
    )
    SELECT 
      kko.ID_ANALYSE_KKO, p_validateur_id, p_statut,
      rc.CODE_SECRET_CODIFICATION, d.REF_DEMANDE, d.AUT_DEMANDE,
      e.RAISONSOCIALE_EXPORTATEUR, l.NUM_LOTS, u.NOM_UTILISATEURS,
      d.CAMP_DEMANDE, d.VILLE_DEMANDE, kko.DATE_ANALYSE_KKO,
      kko.POIDS_BRISURES, kko.POIDS_DECHET, kko.POIDS_CRABOT, kko.POIDS_ETRANGERES,
      kko.GRAINAGE, kko.TAUXHUMIDITE, kko.MOISIE_CALCULE, kko.MITEE_CALCULE,
      kko.ARDOISEE_CALCULE, kko.PLATE_CALCULE, kko.GERMEE_CALCULE, kko.VIOLETTE_CALCULE,
      kko.NORME_IVOIRIENNE, kko.NORME_INTERNATIONALE, kko.CONFORME, kko.REMARQUE,
      kko.POIDS_DECLARATION, kko.POIDS_ECHAN_ANALYSE_KKO, kko.POIDS_TOTAL_ECHANTILLON,
      kko.MOISIE_TOTAL, kko.MITEE_TOTAL, kko.ARDOISEE_TOTAL, kko.PLATE_TOTAL, kko.GERMEE_TOTAL, kko.VIOLETTE_TOTAL,
      kko.TAUXBRISURE, kko.TAUXDECHETS, kko.TAUXCRABOT, kko.TAUXMATIERE, kko.TOTAL_DEFECTUEUSES
    FROM kko_analyses kko
    LEFT JOIN registre_codification rc ON kko.ID_CODIFICATION = rc.ID_CODIFICATION
    LEFT JOIN resgistre_sondage rs ON rc.ID_SONDAGE = rs.ID_SONDAGE
    LEFT JOIN lots l ON rs.ID_Lot = l.ID_LOTS
    LEFT JOIN demandes d ON l.ID_DEMANDE = d.ID_DEMANDE
    LEFT JOIN exportateurs e ON d.ID_EXPORTATEUR = e.ID_EXPORTATEUR
    LEFT JOIN utilisateurs u ON kko.ANALYSEUR_ANALYSE_KKO = u.ID_UTILISATEURS
    WHERE kko.ID_ANALYSE_KKO = p_id_analyse_kko;
  ELSE
    -- Mettre à jour le statut si l'analyse existe déjà
    UPDATE validation_bv
    SET STATUT_VALIDATION = p_statut,
        VALIDATEUR_ID = p_validateur_id,
        VALIDATION_DATE = NOW()
    WHERE ID_ANALYSE_KKO = p_id_analyse_kko;
  END IF;
END$$

--
-- Fonctions
--
DROP FUNCTION IF EXISTS `fn_calculer_defectueuses`$$
CREATE DEFINER=`root`@`localhost` FUNCTION `fn_calculer_defectueuses` (`p_germee` FLOAT, `p_plate` FLOAT, `p_mitee` FLOAT) RETURNS FLOAT DETERMINISTIC BEGIN
  RETURN COALESCE(p_germee, 0) + COALESCE(p_plate, 0) + COALESCE(p_mitee, 0);
END$$

