--
-- Structure de la table `factures`
--

DROP TABLE IF EXISTS `factures`;
CREATE TABLE IF NOT EXISTS `factures` (
  `ID_FACTURES` int NOT NULL AUTO_INCREMENT,
  `REF_FACUTRES` varchar(30) DEFAULT NULL,
  `CAMPAGNE_FACTURES` varchar(20) DEFAULT NULL,
  `DATE_FACTURES` date DEFAULT NULL,
  `DATEDEPOT_FACTURES` date DEFAULT NULL,
  `DATEREGLEMENT_FACTUTRES` date DEFAULT NULL,
  `MONTANT_FACTURES` double(15,0) DEFAULT NULL,
  `ID_DEMANDES` int DEFAULT NULL,
  `NBRE_LOTS_FACTURES` int DEFAULT NULL,
  `EN_LIGNE_FACTURES` varchar(30) DEFAULT 'Pas en Ligne',
  `VALIDER` varchar(30) DEFAULT 'Non Valid e',
  `CODE_POSTE_CONTROLE` varchar(20) DEFAULT NULL,
  `ID_RECAP` int DEFAULT NULL,
  PRIMARY KEY (`ID_FACTURES`) USING BTREE,
  UNIQUE KEY `ID_FACTURES` (`ID_FACTURES`) USING BTREE,
  KEY `REF_FACTURES` (`REF_FACUTRES`) USING BTREE,
  KEY `ID_DEMANDES` (`ID_DEMANDES`) USING BTREE,
  KEY `ID_RECAP` (`ID_RECAP`) USING BTREE,
  KEY `CAMPAGNE_FACTURES` (`CAMPAGNE_FACTURES`) USING BTREE,
  KEY `idx_id_recap` (`ID_RECAP`)
) ENGINE=InnoDB AUTO_INCREMENT=11140 AVG_ROW_LENGTH=114 DEFAULT CHARSET=latin1;

