  `MOISIE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total moisi (P1+P2+P3)',
  `MITEE_PLATEAU1` float(9,3) DEFAULT NULL COMMENT 'Mitée plateau 1',
  `MITEE_PLATEAU2` float(9,3) DEFAULT NULL COMMENT 'Mitée plateau 2',
  `MITEE_PLATEAU3` float(9,3) DEFAULT NULL COMMENT 'Mitée plateau 3',
  `MITEE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total mitée (P1+P2+P3)',
  `ARDOISEE_PLATEAU1` float(9,3) DEFAULT NULL COMMENT 'Ardoisée plateau 1',
  `ARDOISEE_PLATEAU2` float(9,3) DEFAULT NULL COMMENT 'Ardoisée plateau 2',
  `ARDOISEE_PLATEAU3` float(9,3) DEFAULT NULL COMMENT 'Ardoisée plateau 3',
  `ARDOISEE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total ardoisée (P1+P2+P3)',
  `PLATE_PLATEAU1` float(9,3) DEFAULT NULL COMMENT 'Plate plateau 1',
  `PLATE_PLATEAU2` float(9,3) DEFAULT NULL COMMENT 'Plate plateau 2',
  `PLATE_PLATEAU3` float(9,3) DEFAULT NULL COMMENT 'Plate plateau 3',
  `PLATE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total plate (P1+P2+P3)',
  `GERMEE_PLATEAU1` float(9,3) DEFAULT NULL COMMENT 'Germée plateau 1',
  `GERMEE_PLATEAU2` float(9,3) DEFAULT NULL COMMENT 'Germée plateau 2',
  `GERMEE_PLATEAU3` float(9,3) DEFAULT NULL COMMENT 'Germée plateau 3',
  `GERMEE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total germée (P1+P2+P3)',
  `VIOLETTE_PLATEAU1` float(9,3) DEFAULT NULL COMMENT 'Violette plateau 1',
  `VIOLETTE_PLATEAU2` float(9,3) DEFAULT NULL COMMENT 'Violette plateau 2',
  `VIOLETTE_PLATEAU3` float(9,3) DEFAULT NULL COMMENT 'Violette plateau 3',
  `VIOLETTE_TOTAL` float(9,3) DEFAULT NULL COMMENT 'Total violette (P1+P2+P3)',
  `NBRE_FEVES_DEFAUTS` int DEFAULT NULL COMMENT 'Nombre de fèves examinées pour les défauts',
  `TOTAL_DEFECTUEUSES` float(9,3) DEFAULT NULL COMMENT 'Total défauts défectueuses (germée+plate+mitée)',
  `POIDS_NOMBRE_FEVES_ENTIERES` float(9,3) DEFAULT NULL COMMENT 'Poids du nombre de fèves entières (300g - total des défauts)',
  PRIMARY KEY (`ID_ANALYSE_KKO`) USING BTREE,
  UNIQUE KEY `ID_ANALYSE_KKO` (`ID_ANALYSE_KKO`) USING BTREE,
  KEY `REF_BV_ANALYSE_KKO` (`REF_BV_ANALYSE_KKO`) USING BTREE,
