  KEY `ID_GRADE_NI` (`ID_GRADE_NI`) USING BTREE,
  KEY `ID_GRADE_FCC` (`ID_GRADE_FCC`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=69712 AVG_ROW_LENGTH=207 DEFAULT CHARSET=latin1;

