--
-- Structure de la table `lots`
--

DROP TABLE IF EXISTS `lots`;
CREATE TABLE IF NOT EXISTS `lots` (
  `ID_LOTS` int NOT NULL AUTO_INCREMENT,
  `NUM_LOTS` varchar(20) DEFAULT NULL,
  `NBRESAC_LOTS` int DEFAULT NULL,
  `POIDS_LOTS` int DEFAULT NULL,
  `RECOLTE_LOTS` varchar(10) DEFAULT NULL,
  `ORIGINE_LOTS` varchar(20) DEFAULT NULL,
  `STATUT_LOTS` int DEFAULT NULL,
  `ID_GRADE` varchar(10) DEFAULT NULL,
  `ID_ENTREPOT` int DEFAULT NULL,
  `ID_MARQUE` int DEFAULT NULL,
  `ID_DEMANDE` int DEFAULT NULL,
  `ANALYSE_LOTS` int DEFAULT NULL,
  `NUM_SCELLE1` varchar(30) DEFAULT NULL,
  `NUM_SCELLE2` varchar(30) DEFAULT NULL,
  `ETAPE_TRAITEMENT_LOTS` varchar(80) DEFAULT 'NON',
  `ETAT_LOTS` tinyint DEFAULT NULL,
  `ETAT_CODIFICATION_LOTS` varchar(10) DEFAULT 'NON',
  `ETAT_SONDAGE_LOTS` varchar(5) DEFAULT 'NON',
  `ETAT_BRASSAGE` varchar(50) DEFAULT 'NON',
  PRIMARY KEY (`ID_LOTS`) USING BTREE,
  UNIQUE KEY `ID_LOTS` (`ID_LOTS`) USING BTREE,
  KEY `NUM_LOTS` (`NUM_LOTS`) USING BTREE,
  KEY `ID_GRADE` (`ID_GRADE`) USING BTREE,
