  KEY `ID_DEMANDE` (`ID_DEMANDE`) USING BTREE,
  KEY `ID_MARQUE` (`ID_MARQUE`) USING BTREE,
  KEY `ETAT_CODIFICATION_LOTS` (`ETAT_CODIFICATION_LOTS`) USING BTREE,
  KEY `ETAPE_TRAITEMENT_LOTS` (`ETAPE_TRAITEMENT_LOTS`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=123581 AVG_ROW_LENGTH=120 DEFAULT CHARSET=latin1;

