  `CODE_NATURE_PRESTATION` varchar(20) NOT NULL COMMENT 'Code nature prestation',
  `LIBELLE_NATURE_PRESTATION` varchar(120) DEFAULT NULL COMMENT 'Le libell  de la nature de la prestation',
