  `CODE_NIVEAU_TRAITEMENT` varchar(20) NOT NULL COMMENT 'Le code du niveau de traitement de l''echantillon',
  `LIBELLE_NIVEAU_TRAITEMENT` varchar(120) NOT NULL COMMENT 'Le libell  du niveau de traitement',
  `ORDRE_NIVEAU_TRAITEMENT` tinyint DEFAULT NULL COMMENT 'L''ordre du niveau de traitement de l''echantillon',
  `CMT_NIVEAU_TRAITEMENT` text COMMENT 'Description du niveau de traitement',
