  `POIDS_BRISURES` float(9,3) DEFAULT NULL,
  `POIDS_DECHET` float(9,3) DEFAULT NULL,
  `POIDS_CRABOT` float(9,3) DEFAULT NULL,
  `POIDS_ETRANGERES` float(9,3) DEFAULT NULL,
  `GRAINAGE` double(15,3) DEFAULT NULL,
