  `ARDOISEE_CALCULE` float(9,2) DEFAULT NULL,
  `PLATE_CALCULE` float(9,2) DEFAULT NULL,
  `GERMEE_CALCULE` float(9,2) DEFAULT NULL,
  `VIOLETTE_CALCULE` float(9,2) DEFAULT NULL,
  `NORME_IVOIRIENNE` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `NORME_INTERNATIONALE` varchar(50) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `CONFORME` tinyint(1) DEFAULT '0',
  `REMARQUE` text COLLATE utf8mb4_unicode_ci,
  `VALIDATION_DATE` datetime DEFAULT CURRENT_TIMESTAMP,
  `VALIDATEUR_ID` int DEFAULT NULL,
  `STATUT_VALIDATION` enum('VALIDEE','MODIFIEE','REJETEE') COLLATE utf8mb4_unicode_ci DEFAULT 'VALIDEE',
  `POIDS_DECLARATION` float(9,2) DEFAULT NULL,
  `POIDS_ECHAN_ANALYSE_KKO` float(9,3) DEFAULT NULL,
  `POIDS_TOTAL_ECHANTILLON` float(9,3) DEFAULT NULL,
  `MOISIE_TOTAL` float(9,3) DEFAULT NULL,
  `MITEE_TOTAL` float(9,3) DEFAULT NULL,
