  `VIOLETTE_TOTAL` float(9,3) DEFAULT NULL,
  `TAUXBRISURE` float(9,1) DEFAULT NULL,
  `TAUXDECHETS` float(9,1) DEFAULT NULL,
  `TAUXCRABOT` float(9,1) DEFAULT NULL,
  `TAUXMATIERE` float(9,1) DEFAULT NULL,
  `TOTAL_DEFECTUEUSES` float(9,3) DEFAULT NULL,
  PRIMARY KEY (`ID_VALIDATION_BV`),
  KEY `fk_validation_analyse` (`ID_ANALYSE_KKO`),
  KEY `fk_validation_validateur` (`VALIDATEUR_ID`),
  KEY `idx_code_secret` (`CODE_SECRET_CODIFICATION`),
  KEY `idx_ref_demande` (`REF_DEMANDE`),
  KEY `idx_num_lot` (`NUM_LOTS`),
  KEY `idx_exportateur` (`RAISONSOCIALE_EXPORTATEUR`),
  KEY `idx_date_validation` (`VALIDATION_DATE`),
  KEY `idx_statut` (`STATUT_VALIDATION`),
  KEY `idx_campagne` (`CAMP_DEMANDE`),
  KEY `idx_ville` (`VILLE_DEMANDE`)
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

