--
-- Déclencheurs `validation_bv`
--
DROP TRIGGER IF EXISTS `after_validation_bv_delete`;
DELIMITER $$
CREATE TRIGGER `after_validation_bv_delete` AFTER DELETE ON `validation_bv` FOR EACH ROW BEGIN
  -- Réinitialiser le statut de validation
  UPDATE kko_analyses 
  SET VALIDER_ANALYSE_KKO = 0,
      SIGNER_ANALYSE_KKO = 0
  WHERE ID_ANALYSE_KKO = OLD.ID_ANALYSE_KKO;
END
$$
DELIMITER ;
DROP TRIGGER IF EXISTS `after_validation_bv_insert`;
DELIMITER $$
CREATE TRIGGER `after_validation_bv_insert` AFTER INSERT ON `validation_bv` FOR EACH ROW BEGIN
  -- Marquer l'analyse comme validée dans la table originale
  UPDATE kko_analyses 
  SET VALIDER_ANALYSE_KKO = 1,
      SIGNER_ANALYSE_KKO = 1
  WHERE ID_ANALYSE_KKO = NEW.ID_ANALYSE_KKO;
END
$$
DELIMITER ;

